use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let units = input[0].as_i64().unwrap();
    let quantity = input[1].as_i64().unwrap();
    let total_cents = units * 100 + quantity
    let total_cents = total_cents as i64;
    let total_cents = total_cents / 100;
    Value::from(total_cents)
}
